p[57] = "ไม่ว่าจะอย่างไร การทวงอำนาจคืนย่อมสำคัญเหนือสิ่งอื่นใด ส่วนเรื่องการต่อรองกับลีออนในภายภาคหน้านั้น นางยังมีหนทางอื่นอีก ไม่ได้มีเพียงวิธีนี้วิธีเดียว"
p[58] = "รอสวิธาเม้มปาก เก็บจดหมายกลับเข้าลิ้นชักแล้วลงกลอนแน่นหนา จากนั้นจึงลุกขึ้นเดินออกจากห้องหนังสือกลับไปยังห้องนอน"
p[60] = "หลังผลัดเปลี่ยนเสื้อผ้าเสร็จสรรพ นางก็ลอบถอนใจยาวอย่างโล่งอก"
p[61] = "ติ๊ก-ต็อก... เสียงเข็มนาฬิกาบนฝาผนังดังสม่ำเสมอ รอสวิธาเหลียวมองก็พบว่าล่วงเข้าเที่ยงคืนแล้ว"
p[62] = "ความง่วงงุนเริ่มเข้าจู่โจม ในที่สุดค่ำคืนนี้นางก็ได้เข้านอนพักผ่อนเร็วขึ้นเสียที นางถอดรองเท้าแตะ ก้าวขึ้นเตียงแล้วดึงผ้าห่มขึ้นมาคลุมกาย"
p[63] = "ขณะเอนหลังพิงหัวเตียง สายตาของรอสวิธาก็บังเอิญเหลือบไปเห็นตุ๊กตาหมีตัวใหญ่ที่วางอยู่ข้างตัว"
p[64] = "แววตาสีเงินวาวโรจน์ขึ้นชั่วพริบตา นางเอื้อมมือไปคว้าตุ๊กตาหมีตัวนั้นมารัวหมัดใส่หน้าอันนุ่มนิ่มของมันไม่ยั้ง!"
p[65] = '"ไอ้เจ้าหมาบ้า ไอ้คนสารเลว ไปลงนรกซะเถอะแก!" นางทุบพลางก่นด่าระบายแค้นอยู่ในลำคอ'
p[73] = "ลีออนบอกว่าตอนนี้มูนกำลังอยู่ในช่วงตื่นรู้ทางเวทมนตร์และเริ่มแสดงสัญญาณของพรสวรรค์ออกมาแล้ว พวกเขาจึงจำเป็นต้องคอยดูแลแกอย่างใกล้ชิดเป็นพิเศษ"
p[75] = "ในฐานะน้องสาวของอัจฉริยะ แม้ปกติจะทำตัวเป็นเพียงมาสคอตตัวกลมประจำบ้าน ทว่าพรสวรรค์ของมูนก็โดดเด่นน่าทึ่งยิ่งนักยามที่แกตั้งใจเรียนรู้จริงๆ"

